xql_query:
// ============================================================
// Rule: CTX_RBAC_Role_Edited
// Vendor: Cortex
// Objective:
// Detect activity associated with CTX_RBAC_Role_Edited.
// Severity: SEV_040_HIGH
// Category: PRIVILEGE_ESCALATION
// ============================================================
// MITRE ATT&CK:
// Tactic: TA0004 - Privilege Escalation
// Technique: T1098 - Account Manipulation

// Configuração inicial: define que as comparações NÃO diferenciam maiúsculas/minúsculas
// Motivo: reduz risco de perda de eventos por variação de caixa no campo subtype/description (ex.: "Role Edited" vs "role edited")
config case_sensitive = false

// Fonte de dados: Management Audit Logs do Cortex
// O dataset 'management_auditing' registra ações administrativas executadas no console,
// incluindo alterações de configuração, auditoria de RBAC e mudanças em permissões/roles.
| dataset = management_auditing

// Seleção dos campos principais para auditoria e correlação
// Objetivo: capturar quem executou a ação, qual ação ocorreu e o detalhe do objeto impactado.
| fields
    _time,                    // Data/hora do evento (timestamp)
    user_name,                // Usuário administrador que realizou a ação no console
    management_auditing_type, // Categoria do evento de auditoria (ex.: configuração, RBAC, etc.)
    subtype,                  // Subtipo/ação específica registrada (ex.: "Role Edited")
    description               // Descrição detalhada (normalmente inclui role afetada e contexto da mudança)

// Filtro: monitora edição de Roles (RBAC)
// "Role Edited" indica alteração em uma Role existente, podendo impactar permissões e acesso ao tenant.
| filter subtype contains "Role Edited"

// Agrupamento temporal para uso em correlação (ex.: múltiplas edições em curto período)
// Observação: o bin prepara o dado para regras correlacionadas por janela, mesmo que a query final mostre eventos individuais.
| bin _time span = 1h

// Saída final: campos recomendados para correlação e notificação do alerta
| fields
    _time,
    user_name,
    management_auditing_type,
    subtype,
    description

